CREATE TABLE IF NOT EXISTS "agents" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Sign-in identity for a staff member. Agents occupy a paid seat; requesters never do.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown on public replies. Kept separate from the login so a team can present a first name only.
	"display_name" VARCHAR(120) NOT NULL,
	-- agent | lead | admin. Leads can reassign across queues; admins edit SLA policies and macros.
	"role" VARCHAR(24) NOT NULL DEFAULT 'agent',
	-- Appended to public replies. Null means the queue or brand default is used.
	"signature" TEXT,
	-- Cap used by load-balanced assignment. Null means no cap.
	"max_open_tickets" INTEGER,
	-- Deactivated agents keep their authored messages, which is why the row is never deleted.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- When the seat was created.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "agents" IS 'Support staff. Deliberately a different table from customers: the two have different identity rules, different retention obligations and different billing consequences, and merging them is what makes an internal note leak.';
COMMENT ON COLUMN "agents"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "agents"."email" IS 'Sign-in identity for a staff member. Agents occupy a paid seat; requesters never do.';
COMMENT ON COLUMN "agents"."display_name" IS 'Name shown on public replies. Kept separate from the login so a team can present a first name only.';
COMMENT ON COLUMN "agents"."role" IS 'agent | lead | admin. Leads can reassign across queues; admins edit SLA policies and macros.';
COMMENT ON COLUMN "agents"."signature" IS 'Appended to public replies. Null means the queue or brand default is used.';
COMMENT ON COLUMN "agents"."max_open_tickets" IS 'Cap used by load-balanced assignment. Null means no cap.';
COMMENT ON COLUMN "agents"."is_active" IS 'Deactivated agents keep their authored messages, which is why the row is never deleted.';
COMMENT ON COLUMN "agents"."created_at" IS 'When the seat was created.';

CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Primary address. Inbound mail is matched on it, which is how an email thread finds its existing requester.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Null until the person tells you, because an email-only ticket has no name to start with.
	"full_name" VARCHAR(160),
	-- Id of this person in the product being supported, so an agent can open the real account.
	"external_ref" VARCHAR(120),
	-- Free-text organisation. A real account object lives in the CRM, not here.
	"company" VARCHAR(160),
	-- BCP 47 tag. Chooses the language of automated replies and satisfaction surveys.
	"locale" VARCHAR(12),
	-- First contact, used to distinguish new requesters from returning ones in reporting.
	"first_seen_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'The person asking for help. Created implicitly by the first inbound message, so almost every column except the address has to be nullable.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."email" IS 'Primary address. Inbound mail is matched on it, which is how an email thread finds its existing requester.';
COMMENT ON COLUMN "customers"."full_name" IS 'Null until the person tells you, because an email-only ticket has no name to start with.';
COMMENT ON COLUMN "customers"."external_ref" IS 'Id of this person in the product being supported, so an agent can open the real account.';
COMMENT ON COLUMN "customers"."company" IS 'Free-text organisation. A real account object lives in the CRM, not here.';
COMMENT ON COLUMN "customers"."locale" IS 'BCP 47 tag. Chooses the language of automated replies and satisfaction surveys.';
COMMENT ON COLUMN "customers"."first_seen_at" IS 'First contact, used to distinguish new requesters from returning ones in reporting.';

CREATE TABLE IF NOT EXISTS "business_calendars" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Label such as "EMEA business hours" or "24/7".
	"name" VARCHAR(80) NOT NULL,
	-- IANA zone. Stored as a name, not an offset, so the calendar follows daylight saving on its own.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Array of local dates on which the clock does not run. JSON because the list is edited as a whole, never queried by date.
	"holiday_dates" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "business_calendars" IS 'A named schedule that SLA clocks run against. The timezone lives here rather than on the ticket because an SLA is a promise made by the support team, in the team calendar, not in the requester local time.';
COMMENT ON COLUMN "business_calendars"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "business_calendars"."name" IS 'Label such as "EMEA business hours" or "24/7".';
COMMENT ON COLUMN "business_calendars"."timezone" IS 'IANA zone. Stored as a name, not an offset, so the calendar follows daylight saving on its own.';
COMMENT ON COLUMN "business_calendars"."holiday_dates" IS 'Array of local dates on which the clock does not run. JSON because the list is edited as a whole, never queried by date.';

CREATE TABLE IF NOT EXISTS "business_hours" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Calendar this window belongs to.
	"calendar_id" BIGINT NOT NULL,
	-- 0 = Sunday through 6 = Saturday. A weekday with no rows is a non-working day.
	"weekday" SMALLINT NOT NULL,
	-- Local opening time in the calendar timezone.
	"opens_at" TIME NOT NULL,
	-- Local closing time. Must be later than opens_at; overnight coverage is two rows on consecutive weekdays.
	"closes_at" TIME NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "business_hours" IS 'One row per open window. Several rows per weekday are allowed on purpose, so a desk that closes for lunch or runs split shifts does not need a second calendar.';
COMMENT ON COLUMN "business_hours"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "business_hours"."calendar_id" IS 'Calendar this window belongs to.';
COMMENT ON COLUMN "business_hours"."weekday" IS '0 = Sunday through 6 = Saturday. A weekday with no rows is a non-working day.';
COMMENT ON COLUMN "business_hours"."opens_at" IS 'Local opening time in the calendar timezone.';
COMMENT ON COLUMN "business_hours"."closes_at" IS 'Local closing time. Must be later than opens_at; overnight coverage is two rows on consecutive weekdays.';

CREATE UNIQUE INDEX "uq_business_hours_slot"
ON "business_hours" ("calendar_id", "weekday", "opens_at");

CREATE TABLE IF NOT EXISTS "queues" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable identifier used by routing and inbound mail aliases.
	"key" VARCHAR(40) NOT NULL UNIQUE,
	-- Display name, e.g. "Billing".
	"name" VARCHAR(120) NOT NULL,
	-- Business calendar for tickets in this queue. Null means the 24/7 default.
	"calendar_id" BIGINT,
	-- Policy applied when a ticket lands here and no rule picks a more specific one.
	"default_sla_policy_id" BIGINT,
	-- manual | round_robin | least_busy. Auto-assignment is a queue property because that is the unit a team owns.
	"assignment_strategy" VARCHAR(24) NOT NULL DEFAULT 'manual',
	-- Where an unanswered ticket is escalated to. Self-reference; null ends the chain.
	"escalation_queue_id" BIGINT,
	-- Inactive queues stop accepting new tickets but keep their history.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "queues" IS 'The routing bucket and the unit of team ownership. Business hours, default SLA and escalation all hang off the queue, so moving a ticket between queues re-evaluates all three at once.';
COMMENT ON COLUMN "queues"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "queues"."key" IS 'Stable identifier used by routing and inbound mail aliases.';
COMMENT ON COLUMN "queues"."name" IS 'Display name, e.g. "Billing".';
COMMENT ON COLUMN "queues"."calendar_id" IS 'Business calendar for tickets in this queue. Null means the 24/7 default.';
COMMENT ON COLUMN "queues"."default_sla_policy_id" IS 'Policy applied when a ticket lands here and no rule picks a more specific one.';
COMMENT ON COLUMN "queues"."assignment_strategy" IS 'manual | round_robin | least_busy. Auto-assignment is a queue property because that is the unit a team owns.';
COMMENT ON COLUMN "queues"."escalation_queue_id" IS 'Where an unanswered ticket is escalated to. Self-reference; null ends the chain.';
COMMENT ON COLUMN "queues"."is_active" IS 'Inactive queues stop accepting new tickets but keep their history.';

CREATE TABLE IF NOT EXISTS "sla_policies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Label such as "Enterprise, urgent".
	"name" VARCHAR(120) NOT NULL,
	-- urgent | high | normal | low. The policy is selected by priority, which is why priority is not just a display badge.
	"priority" VARCHAR(16) NOT NULL DEFAULT 'normal',
	-- Calendar the targets are measured against.
	"calendar_id" BIGINT NOT NULL,
	-- Business minutes allowed before the first public agent reply. Null means no first-response promise.
	"first_response_minutes" INTEGER,
	-- Business minutes allowed for each subsequent reply after the customer writes back.
	"next_response_minutes" INTEGER,
	-- Business minutes allowed before the ticket is solved.
	"resolution_minutes" INTEGER,
	-- Business minutes of inactivity before the ticket moves to the queue escalation target.
	"escalate_after_minutes" INTEGER,
	-- Retired policies stay so historical targets still resolve to the terms that were promised.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sla_policies" IS 'The promise, expressed in business minutes rather than wall-clock minutes. Targets are stored as durations and materialised per ticket, so editing a policy never silently rewrites the deadlines of tickets already in flight.';
COMMENT ON COLUMN "sla_policies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sla_policies"."name" IS 'Label such as "Enterprise, urgent".';
COMMENT ON COLUMN "sla_policies"."priority" IS 'urgent | high | normal | low. The policy is selected by priority, which is why priority is not just a display badge.';
COMMENT ON COLUMN "sla_policies"."calendar_id" IS 'Calendar the targets are measured against.';
COMMENT ON COLUMN "sla_policies"."first_response_minutes" IS 'Business minutes allowed before the first public agent reply. Null means no first-response promise.';
COMMENT ON COLUMN "sla_policies"."next_response_minutes" IS 'Business minutes allowed for each subsequent reply after the customer writes back.';
COMMENT ON COLUMN "sla_policies"."resolution_minutes" IS 'Business minutes allowed before the ticket is solved.';
COMMENT ON COLUMN "sla_policies"."escalate_after_minutes" IS 'Business minutes of inactivity before the ticket moves to the queue escalation target.';
COMMENT ON COLUMN "sla_policies"."is_active" IS 'Retired policies stay so historical targets still resolve to the terms that were promised.';

CREATE TABLE IF NOT EXISTS "tickets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Human-facing number quoted in emails. Separate from the id so it can be sequential and pretty without leaking row counts.
	"reference" VARCHAR(20) NOT NULL UNIQUE,
	-- Current queue. Changing it re-runs SLA and escalation selection.
	"queue_id" BIGINT NOT NULL,
	-- The requester.
	"customer_id" BIGINT NOT NULL,
	-- Current owner. Null is a real and common state: unassigned tickets are the queue backlog.
	"assignee_agent_id" BIGINT,
	-- Policy in force. Null for tickets created before any policy existed.
	"sla_policy_id" BIGINT,
	-- Subject line, seeded from the inbound email.
	"subject" VARCHAR(255) NOT NULL,
	-- new | open | pending | on_hold | solved | closed | merged. pending means waiting on the customer, which pauses response clocks.
	"status" VARCHAR(20) NOT NULL DEFAULT 'new',
	-- urgent | high | normal | low. Drives which SLA policy applies.
	"priority" VARCHAR(16) NOT NULL DEFAULT 'normal',
	-- email | web | chat | phone | api. Recorded because first-response expectations differ wildly by channel.
	"channel" VARCHAR(16) NOT NULL DEFAULT 'email',
	-- Timestamp of the first public agent reply. Denormalised from ticket_messages because every SLA report reads it.
	"first_response_at" TIMESTAMP,
	-- Used to restart the next-response clock and to find tickets gone quiet.
	"last_customer_reply_at" TIMESTAMP,
	-- How many times a solved ticket came back. A high value usually means the first fix was wrong, not that the customer is difficult.
	"reopen_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time, the anchor for every SLA clock on the ticket.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When an agent marked it solved. Cleared on reopen.
	"solved_at" TIMESTAMP,
	-- When it became immutable. Closing is separate from solving so a customer has a window to reopen.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tickets" IS 'The unit of work. It carries no message text at all: the conversation is rows in ticket_messages, which is what lets the same ticket hold a public thread and a private one without the two ever sharing a column.';
COMMENT ON COLUMN "tickets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "tickets"."reference" IS 'Human-facing number quoted in emails. Separate from the id so it can be sequential and pretty without leaking row counts.';
COMMENT ON COLUMN "tickets"."queue_id" IS 'Current queue. Changing it re-runs SLA and escalation selection.';
COMMENT ON COLUMN "tickets"."customer_id" IS 'The requester.';
COMMENT ON COLUMN "tickets"."assignee_agent_id" IS 'Current owner. Null is a real and common state: unassigned tickets are the queue backlog.';
COMMENT ON COLUMN "tickets"."sla_policy_id" IS 'Policy in force. Null for tickets created before any policy existed.';
COMMENT ON COLUMN "tickets"."subject" IS 'Subject line, seeded from the inbound email.';
COMMENT ON COLUMN "tickets"."status" IS 'new | open | pending | on_hold | solved | closed | merged. pending means waiting on the customer, which pauses response clocks.';
COMMENT ON COLUMN "tickets"."priority" IS 'urgent | high | normal | low. Drives which SLA policy applies.';
COMMENT ON COLUMN "tickets"."channel" IS 'email | web | chat | phone | api. Recorded because first-response expectations differ wildly by channel.';
COMMENT ON COLUMN "tickets"."first_response_at" IS 'Timestamp of the first public agent reply. Denormalised from ticket_messages because every SLA report reads it.';
COMMENT ON COLUMN "tickets"."last_customer_reply_at" IS 'Used to restart the next-response clock and to find tickets gone quiet.';
COMMENT ON COLUMN "tickets"."reopen_count" IS 'How many times a solved ticket came back. A high value usually means the first fix was wrong, not that the customer is difficult.';
COMMENT ON COLUMN "tickets"."created_at" IS 'Creation time, the anchor for every SLA clock on the ticket.';
COMMENT ON COLUMN "tickets"."solved_at" IS 'When an agent marked it solved. Cleared on reopen.';
COMMENT ON COLUMN "tickets"."closed_at" IS 'When it became immutable. Closing is separate from solving so a customer has a window to reopen.';

CREATE INDEX "idx_tickets_queue_status"
ON "tickets" ("queue_id", "status", "priority");
CREATE INDEX "idx_tickets_assignee_status"
ON "tickets" ("assignee_agent_id", "status");
CREATE INDEX "idx_tickets_customer_created"
ON "tickets" ("customer_id", "created_at");

CREATE TABLE IF NOT EXISTS "ticket_messages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticket this entry belongs to.
	"ticket_id" BIGINT NOT NULL,
	-- Staff author. Exactly one of author_agent_id and author_customer_id is set; both null means the system wrote it.
	"author_agent_id" BIGINT,
	-- Requester author, set for inbound mail and portal replies.
	"author_customer_id" BIGINT,
	-- public | internal. The single most consequential column in the schema: public is emailed to the requester, internal never leaves the desk.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'public',
	-- Message content as stored, before per-channel rendering.
	"body" TEXT NOT NULL,
	-- RFC 5322 Message-ID of the inbound email. Unique so a duplicate delivery cannot append the same reply twice.
	"source_message_id" VARCHAR(255) UNIQUE,
	-- Macro used to compose this reply, kept to measure which canned answers actually work.
	"via_macro_id" BIGINT,
	-- Ordering key for the thread.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ticket_messages" IS 'One row per conversation entry, public replies and internal notes in the same ordered thread. Splitting them into two tables looks safer but makes the agent view a merge-sort and loses the interleaving that gives a note its context.';
COMMENT ON COLUMN "ticket_messages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ticket_messages"."ticket_id" IS 'Ticket this entry belongs to.';
COMMENT ON COLUMN "ticket_messages"."author_agent_id" IS 'Staff author. Exactly one of author_agent_id and author_customer_id is set; both null means the system wrote it.';
COMMENT ON COLUMN "ticket_messages"."author_customer_id" IS 'Requester author, set for inbound mail and portal replies.';
COMMENT ON COLUMN "ticket_messages"."visibility" IS 'public | internal. The single most consequential column in the schema: public is emailed to the requester, internal never leaves the desk.';
COMMENT ON COLUMN "ticket_messages"."body" IS 'Message content as stored, before per-channel rendering.';
COMMENT ON COLUMN "ticket_messages"."source_message_id" IS 'RFC 5322 Message-ID of the inbound email. Unique so a duplicate delivery cannot append the same reply twice.';
COMMENT ON COLUMN "ticket_messages"."via_macro_id" IS 'Macro used to compose this reply, kept to measure which canned answers actually work.';
COMMENT ON COLUMN "ticket_messages"."created_at" IS 'Ordering key for the thread.';

CREATE INDEX "idx_ticket_messages_thread"
ON "ticket_messages" ("ticket_id", "created_at");
CREATE INDEX "idx_ticket_messages_visibility"
ON "ticket_messages" ("ticket_id", "visibility");

CREATE TABLE IF NOT EXISTS "ticket_sla_targets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticket being measured.
	"ticket_id" BIGINT NOT NULL,
	-- Policy the target came from, snapshotted so later edits to the policy do not move an existing deadline.
	"sla_policy_id" BIGINT,
	-- first_response | next_response | resolution. next_response recurs, so a ticket can have several of those rows.
	"target_kind" VARCHAR(20) NOT NULL,
	-- When this clock began: ticket creation, or the customer reply that restarted it.
	"started_at" TIMESTAMP NOT NULL,
	-- Absolute deadline, computed by walking the calendar business hours forward from started_at.
	"due_at" TIMESTAMP NOT NULL,
	-- Business minutes spent in pending or on_hold. Accumulated here so due_at can be recomputed rather than guessed.
	"paused_minutes" INTEGER NOT NULL DEFAULT 0,
	-- When the required action happened. Null and past due means the target is breached.
	"satisfied_at" TIMESTAMP,
	-- Set once when the deadline passed unmet, so breach counts are a query on stored facts and not a recomputation of history.
	"breached_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ticket_sla_targets" IS 'One row per SLA clock, materialised when the clock starts. Computing breaches on the fly from policy plus calendar is the classic mistake: it makes an at-risk dashboard a full replay of every ticket, and it silently rewrites the past whenever business hours change.';
COMMENT ON COLUMN "ticket_sla_targets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ticket_sla_targets"."ticket_id" IS 'Ticket being measured.';
COMMENT ON COLUMN "ticket_sla_targets"."sla_policy_id" IS 'Policy the target came from, snapshotted so later edits to the policy do not move an existing deadline.';
COMMENT ON COLUMN "ticket_sla_targets"."target_kind" IS 'first_response | next_response | resolution. next_response recurs, so a ticket can have several of those rows.';
COMMENT ON COLUMN "ticket_sla_targets"."started_at" IS 'When this clock began: ticket creation, or the customer reply that restarted it.';
COMMENT ON COLUMN "ticket_sla_targets"."due_at" IS 'Absolute deadline, computed by walking the calendar business hours forward from started_at.';
COMMENT ON COLUMN "ticket_sla_targets"."paused_minutes" IS 'Business minutes spent in pending or on_hold. Accumulated here so due_at can be recomputed rather than guessed.';
COMMENT ON COLUMN "ticket_sla_targets"."satisfied_at" IS 'When the required action happened. Null and past due means the target is breached.';
COMMENT ON COLUMN "ticket_sla_targets"."breached_at" IS 'Set once when the deadline passed unmet, so breach counts are a query on stored facts and not a recomputation of history.';

CREATE UNIQUE INDEX "uq_sla_target_clock"
ON "ticket_sla_targets" ("ticket_id", "target_kind", "started_at");
CREATE INDEX "idx_sla_targets_due"
ON "ticket_sla_targets" ("due_at", "satisfied_at");

CREATE TABLE IF NOT EXISTS "ticket_links" (
	-- Ticket the link is recorded on. Part of the composite key.
	"source_ticket_id" BIGINT,
	-- Ticket being pointed at. Part of the composite key.
	"target_ticket_id" BIGINT,
	-- merged_into | duplicate_of | related | blocked_by. Part of the key, so two tickets can be both related and merged over time.
	"link_type" VARCHAR(20),
	-- Agent who made the link. Null once that agent is deleted.
	"created_by_agent_id" BIGINT,
	-- When the link was made.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("source_ticket_id", "target_ticket_id", "link_type")
);

COMMENT ON TABLE "ticket_links" IS 'Merges and cross-references as edges rather than as a column on the ticket. A merge is then a merged_into edge plus a status change: the absorbed ticket keeps its own URL, reference number and history, so an old email reply still lands somewhere sensible.';
COMMENT ON COLUMN "ticket_links"."source_ticket_id" IS 'Ticket the link is recorded on. Part of the composite key.';
COMMENT ON COLUMN "ticket_links"."target_ticket_id" IS 'Ticket being pointed at. Part of the composite key.';
COMMENT ON COLUMN "ticket_links"."link_type" IS 'merged_into | duplicate_of | related | blocked_by. Part of the key, so two tickets can be both related and merged over time.';
COMMENT ON COLUMN "ticket_links"."created_by_agent_id" IS 'Agent who made the link. Null once that agent is deleted.';
COMMENT ON COLUMN "ticket_links"."created_at" IS 'When the link was made.';

CREATE TABLE IF NOT EXISTS "ticket_tags" (
	-- Tagged ticket. Part of the composite key.
	"ticket_id" BIGINT,
	-- The tag itself, lowercased. Part of the key, which makes double-tagging impossible.
	"tag" VARCHAR(60),
	-- Agent or automation that applied it. Null for system tagging.
	"tagged_by_agent_id" BIGINT,
	-- When it was applied.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("ticket_id", "tag")
);

COMMENT ON TABLE "ticket_tags" IS 'Tags stored as strings on an edge, with no catalogue table. A tags table earns its place only when tags need colours, descriptions or permissions; until then it adds a join to every ticket read and an admin screen nobody visits.';
COMMENT ON COLUMN "ticket_tags"."ticket_id" IS 'Tagged ticket. Part of the composite key.';
COMMENT ON COLUMN "ticket_tags"."tag" IS 'The tag itself, lowercased. Part of the key, which makes double-tagging impossible.';
COMMENT ON COLUMN "ticket_tags"."tagged_by_agent_id" IS 'Agent or automation that applied it. Null for system tagging.';
COMMENT ON COLUMN "ticket_tags"."created_at" IS 'When it was applied.';

CREATE INDEX "idx_ticket_tags_tag"
ON "ticket_tags" ("tag");

CREATE TABLE IF NOT EXISTS "macros" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- What an agent searches for in the composer.
	"name" VARCHAR(120) NOT NULL,
	-- Queue the macro is scoped to. Null makes it available everywhere.
	"queue_id" BIGINT,
	-- Reply template with placeholders such as {{customer.first_name}}, rendered at insert time.
	"body" TEXT NOT NULL,
	-- Side effects applied with the reply: set status, priority, tags, assignee. JSON because the action list changes far more often than the schema should.
	"actions" JSONB,
	-- Incremented on use. The cheapest way to find the macros worth rewriting.
	"usage_count" INTEGER NOT NULL DEFAULT 0,
	-- Author. Null if that agent is gone.
	"created_by_agent_id" BIGINT,
	-- Retired macros stay for the via_macro_id references already recorded on messages.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "macros" IS 'Canned replies with attached side effects. The actions column is what turns a macro from a text snippet into a workflow step, and it is why a macro is worth tracking per use.';
COMMENT ON COLUMN "macros"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "macros"."name" IS 'What an agent searches for in the composer.';
COMMENT ON COLUMN "macros"."queue_id" IS 'Queue the macro is scoped to. Null makes it available everywhere.';
COMMENT ON COLUMN "macros"."body" IS 'Reply template with placeholders such as {{customer.first_name}}, rendered at insert time.';
COMMENT ON COLUMN "macros"."actions" IS 'Side effects applied with the reply: set status, priority, tags, assignee. JSON because the action list changes far more often than the schema should.';
COMMENT ON COLUMN "macros"."usage_count" IS 'Incremented on use. The cheapest way to find the macros worth rewriting.';
COMMENT ON COLUMN "macros"."created_by_agent_id" IS 'Author. Null if that agent is gone.';
COMMENT ON COLUMN "macros"."is_active" IS 'Retired macros stay for the via_macro_id references already recorded on messages.';

CREATE TABLE IF NOT EXISTS "csat_responses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticket rated. Unique, so one survey per ticket and no vote stuffing.
	"ticket_id" BIGINT NOT NULL UNIQUE,
	-- Agent assigned at the moment of solving, snapshotted because later reassignment must not move the score.
	"rated_agent_id" BIGINT,
	-- When the survey went out, typically shortly after solving.
	"sent_at" TIMESTAMP NOT NULL,
	-- Null while the survey is outstanding, which is how response rate is measured.
	"responded_at" TIMESTAMP,
	-- 1 to 5. Null until answered; a satisfaction average that counts unanswered surveys as zero is a broken metric.
	"rating" SMALLINT,
	-- Free-text feedback, often more useful than the number.
	"comment" TEXT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "csat_responses" IS 'Survey outcomes, one per ticket. Keeping the sent and responded timestamps apart means response rate and satisfaction are two separate numbers rather than one misleading one.';
COMMENT ON COLUMN "csat_responses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "csat_responses"."ticket_id" IS 'Ticket rated. Unique, so one survey per ticket and no vote stuffing.';
COMMENT ON COLUMN "csat_responses"."rated_agent_id" IS 'Agent assigned at the moment of solving, snapshotted because later reassignment must not move the score.';
COMMENT ON COLUMN "csat_responses"."sent_at" IS 'When the survey went out, typically shortly after solving.';
COMMENT ON COLUMN "csat_responses"."responded_at" IS 'Null while the survey is outstanding, which is how response rate is measured.';
COMMENT ON COLUMN "csat_responses"."rating" IS '1 to 5. Null until answered; a satisfaction average that counts unanswered surveys as zero is a broken metric.';
COMMENT ON COLUMN "csat_responses"."comment" IS 'Free-text feedback, often more useful than the number.';

CREATE INDEX "idx_csat_agent_responded"
ON "csat_responses" ("rated_agent_id", "responded_at");

